{"summary":"Inspect Answer sheet formulas and blank cells positions","command":"python3 - <<'PY'
import openpyxl
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx', data_only=False)
ws=wb['Answer']
# print coordinates and values for range A1:K24
for r in range(1,25):
    for c in range(1,12):
        v=ws.cell(r,c).value
        if v is not None:
            pass
# show rows 1-6 with columns A-D
for r in range(1,7):
    row=[]
    for c in range(1,6):
        cell=ws.cell(r,c)
        row.append((cell.coordinate,cell.value))
    print('row',r,row)
print('\nStep2 area rows 11-13 columns A-F:')
for r in range(11,14):
    row=[]
    for c in range(1,7):
        cell=ws.cell(r,c)
        row.append((cell.coordinate,cell.value))
    print('row',r,row)
print('\nStep3 area rows 20-24 columns A-H:')
for r in range(20,25):
    row=[]
    for c in range(1,9):
        cell=ws.cell(r,c)
        row.append((cell.coordinate,cell.value))
    print('row',r,row)
PY"}

