{"summary":"Locate last populated row in Gold price column A","command":"python3 - <<'PY'
import openpyxl
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx', data_only=False)
ws=wb['Gold price']
last=0
for r in range(1,ws.max_row+1):
    if ws.cell(r,1).value not in (None,''):
        last=r
print('last row with date in col A:',last,'value',ws.cell(last,1).value)
# show around last
for r in range(max(1,last-5), last+5):
    print(r, ws.cell(r,1).value, ws.cell(r,2).value, ws.cell(r,3).value)
PY"}

