{"summary": "Search workbook for formulas referencing volatility or exposure", "command": "python3 - <<'PY'
import openpyxl, re
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx', data_only=False)
patterns=['VOL','vol','exposure','Z','NORM','CONFIDENCE','NORMSINV']
found=[]
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for cell in row:
            v=cell.value
            if isinstance(v,str) and v.startswith('='):
                if any(p in v for p in patterns):
                    found.append((ws.title, cell.coordinate, v))

print('found',len(found))
for item in found[:50]:
    print(item)
PY"}

