{"summary": "List all non-empty cells in Answer sheet to find instructions", "command": "python3 - <<'PY'
import openpyxl
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx', data_only=False)
ws=wb['Answer']
non=[]
for row in ws.iter_rows():
    for cell in row:
        if cell.value not in (None,''):
            non.append((cell.coordinate, cell.value))
print('non-empty count', len(non))
for coord,val in non:
    print(coord, val)
